// Generated by Suite Builder from a crawl of the site. The suite as a zip to hand on: npm run pack.
// EDIT RULES: do not edit this file; regenerating replaces all of it. Account files go in blank; what is left out, and why, is listed when it runs.
import { existsSync, readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { basename, dirname, join, relative, resolve, sep } from 'node:path';
import { deflateRawSync } from 'node:zlib';

/**
 * The suite as a zip to hand on (G-160): npm run pack, from the suite's folder. Beside the suite,
 * <folder>-pack-<date>.zip, with every account file blank (secrets/*.login), the pages as crawled while the
 * crawl is current (1 days, G-124), and none of what a run leaves or a receiver brings
 * back. It says what it left out, and why. Nothing to install: Node's own zlib.
 *
 * npm run pack -- --run: this run's pack, to send to whoever helps with its failures (G-213).
 * <folder>-run-<date>.zip: the suite as above, and the run's failures, screenshots and reports, without the
 * pages as crawled and without its videos.
 */

/** What is left out, by path prefix, and why (the same in every framework Suite Builder writes). */
const LEAVES_OUT = [
  [".git/", "the repository: the receiver keeps their own"],
  ["target/", "Maven builds it again, and a run's evidence stays with whoever ran it"],
  ["node_modules/", "npm install brings it back"],
  ["cypress/failures/", "a run's evidence stays with whoever ran it"],
  ["cypress/screenshots/", "a run's evidence stays with whoever ran it"],
  ["cypress/videos/", "a run's evidence stays with whoever ran it"],
  ["cypress/results/", "a run's output"],
  ["cypress/downloads/", "a run's output"],
  ["cypress/timings/", "a run's output"],
  ["cypress/timings-previous/", "a run's output"],
  ["cypress/report.html", "a run's output"],
  ["cypress/flaky-tests.txt", "a run's output"],
  ["cypress/rules-report.md", "a run's output"],
  ["cypress/link-report.md", "a run's output"],
];
const BLANK_ACCOUNT = 'Username:\nPassword:\n';
/** The longest path in the zip that still unzips on Windows (260 characters, less room for where it is unzipped). */
const LONGEST_PATH = 160;
const DAY_MS = 24 * 60 * 60 * 1000;
/** What a run's pack adds: the run's evidence and reports, by path prefix. */
const RUN_TAKES = ["target/failures/","target/report.html","target/flaky-tests.txt","target/link-report.md","target/rules-report.md","cypress/failures/","cypress/screenshots/","cypress/report.html","cypress/flaky-tests.txt","cypress/link-report.md","cypress/rules-report.md"];
const run = process.argv.includes('--run');

/** True while the crawl the suite carries is at most 1 days old (crawl/manifest.json). */
function crawlIsCurrent(suite) {
  try {
    const saved = JSON.parse(readFileSync(join(suite, 'crawl', 'manifest.json'), 'utf8')).crawlFileSaved;
    return Boolean(saved) && Math.floor((Date.now() - Date.parse(saved)) / DAY_MS) <= 1;
  } catch {
    return false;
  }
}

/** Why a file stays out of the zip, and what it is said as; null when it goes in. */
function leftOut(rel, pagesCurrent) {
  if (run && rel.startsWith('crawl/pages/')) return { group: 'crawl/pages/', why: 'the pages as crawled: the crawl file holds what they showed, and they can hold personal data' };
  if (run && RUN_TAKES.some((take) => rel === take || (take.endsWith('/') && rel.startsWith(take)))) return null;
  for (const [path, why] of LEAVES_OUT) if (rel === path || (path.endsWith('/') && rel.startsWith(path))) return { group: path, why };
  if (rel.startsWith('saved-pages/') && /\.html?$/.test(rel)) return { group: 'saved-pages/ (the pages; its README goes in)', why: 'saved pages can hold personal data: each receiver saves their own' };
  if (rel.startsWith('crawl/pages/') && !pagesCurrent) return { group: 'crawl/pages/', why: 'the crawl is older than 1 days: crawl again (suite build) to bring them back' };
  return null;
}

function files(dir) {
  return readdirSync(dir, { withFileTypes: true })
    .sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))
    .flatMap((e) => (e.isDirectory() ? files(join(dir, e.name)) : e.isFile() ? [join(dir, e.name)] : []));
}

const CRC = Array.from({ length: 256 }, (_, n) => {
  let c = n;
  for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
  return c >>> 0;
});
function crc32(bytes) {
  let c = 0xffffffff;
  for (const b of bytes) c = CRC[(c ^ b) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}

/** A zip of [name, bytes] entries, deflated, with the time each was packed. */
function zip(entries) {
  const now = new Date();
  const time = (now.getHours() << 11) | (now.getMinutes() << 5) | (now.getSeconds() >> 1);
  const date = ((now.getFullYear() - 1980) << 9) | ((now.getMonth() + 1) << 5) | now.getDate();
  const parts = [];
  const central = [];
  let offset = 0;
  for (const [name, bytes] of entries) {
    const nameBytes = Buffer.from(name, 'utf8');
    const packed = deflateRawSync(bytes);
    const crc = crc32(bytes);
    const local = Buffer.alloc(30);
    local.writeUInt32LE(0x04034b50, 0);
    local.writeUInt16LE(20, 4);
    local.writeUInt16LE(0x0800, 6);
    local.writeUInt16LE(8, 8);
    local.writeUInt16LE(time, 10);
    local.writeUInt16LE(date, 12);
    local.writeUInt32LE(crc, 14);
    local.writeUInt32LE(packed.length, 18);
    local.writeUInt32LE(bytes.length, 22);
    local.writeUInt16LE(nameBytes.length, 26);
    const head = Buffer.alloc(46);
    head.writeUInt32LE(0x02014b50, 0);
    head.writeUInt16LE(20, 4);
    head.writeUInt16LE(20, 6);
    head.writeUInt16LE(0x0800, 8);
    head.writeUInt16LE(8, 10);
    head.writeUInt16LE(time, 12);
    head.writeUInt16LE(date, 14);
    head.writeUInt32LE(crc, 16);
    head.writeUInt32LE(packed.length, 20);
    head.writeUInt32LE(bytes.length, 24);
    head.writeUInt16LE(nameBytes.length, 28);
    head.writeUInt32LE(offset, 42);
    parts.push(local, nameBytes, packed);
    central.push(head, nameBytes);
    offset += local.length + nameBytes.length + packed.length;
  }
  const size = central.reduce((n, b) => n + b.length, 0);
  const end = Buffer.alloc(22);
  end.writeUInt32LE(0x06054b50, 0);
  end.writeUInt16LE(entries.length, 8);
  end.writeUInt16LE(entries.length, 10);
  end.writeUInt32LE(size, 12);
  end.writeUInt32LE(offset, 16);
  return Buffer.concat([...parts, ...central, end]);
}

const suite = resolve('.');
const folder = basename(suite);
if (run && !RUN_TAKES.some((take) => existsSync(join(suite, take)))) {
  console.log('No run here to pack: run the tests first (npm test), then pack it.');
  process.exit(1);
}
const out = join(dirname(suite), `${folder}-${run ? 'run' : 'pack'}-${new Date().toISOString().slice(0, 10)}.zip`);
const pagesCurrent = crawlIsCurrent(suite);
const left = new Map();
const entries = [];
let blanked = 0;
for (const file of files(suite)) {
  const rel = relative(suite, file).split(sep).join('/');
  const reason = leftOut(rel, pagesCurrent);
  if (reason) {
    const was = left.get(reason.group);
    left.set(reason.group, { why: reason.why, count: (was?.count ?? 0) + 1 });
    continue;
  }
  // Every account file blank, whatever this copy holds: the receiver fills in their own.
  const account = rel.startsWith('secrets/') && rel.endsWith('.login');
  if (account) blanked++;
  entries.push([`${folder}/${rel}`, account ? Buffer.from(BLANK_ACCOUNT, 'utf8') : readFileSync(file)]);
}
const packed = zip(entries);
writeFileSync(out, packed);
console.log(`Packed ${entries.length} files into ${out}, ${(packed.length / 1048576).toFixed(1)} MB (${blanked} account file${blanked === 1 ? '' : 's'} blank).`);
if (left.size) console.log('Left out:');
for (const [group, { why, count }] of [...left].sort(([a], [b]) => (a < b ? -1 : 1))) console.log(`  ${group} (${count} file${count === 1 ? '' : 's'}): ${why}`);
const longest = entries.reduce((l, [name]) => (name.length > l.length ? name : l), '');
if (longest.length > LONGEST_PATH) console.log(`Too long for Windows' zip once unzipped (${longest.length} characters; at most ${LONGEST_PATH}): ${longest}. Shorten that name before handing it on.`);
if (run) console.log('The screenshots show the site as the run saw it: signed in, they can show an account\'s data. Look before you send it.');
else console.log('Hand it on as it is; never a copy with a filled account file. The receiver fills in secrets/ (secrets/README.md).');
